#include "dei_rs_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static Evt dei_rs_evt ; 
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

//--------------------------------------------------------------------------//

void dei_rs_evt_init( void )
{
	dei_rs_evt = os_evt_create();
}

//--------------------------------------------------------------------------//

void dei_rs_evt_signal( Dei_Rs_Evt rs_evt )
{
	os_evt_signal( dei_rs_evt , 1 << rs_evt ) ; 
}

//--------------------------------------------------------------------------//

Dei_Rs_Evt dei_rs_evt_wait( UInt16 event_msk , TskTimeout timeout )
{
	UInt8 i ;

	UInt16 event  = os_evt_wait( dei_rs_evt  , event_msk , event_msk , timeout ) ;

	for( i = 0  ; i < 16 ; i ++ )
	{
		if( (event & ( (UInt16)1 << i) ))return (Dei_Rs_Evt)i ; 
	}

	return DEI_RS_EVT_TIMEOUT ; 
}

